pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 dep, uint256 am) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(0) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        vm.assume(am <= c.balances(address(this)));
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) + am == balBefore && address(c).balance + am == ethBefore);
    }

    function testFuzz_run(uint256 dep, uint256 am) public {
        _run(dep, am);
    }

    receive() external payable {}
}
